/-- The Calderon Zygmund operator `T_r` in chapter Two-sided Metric Space Carleson -/
def CZOperator (K : X → X → ℂ) (r : ℝ) (f : X → ℂ) (x : X) : ℂ :=
  ∫ y in (ball x r)ᶜ, K x y * f y

